using Rts.Sim.Core;
using Rts.Sim.Garrison;
using Rts.Sim.Stats;

namespace Rts.Sim;

// M4 coordination (OWNER: M4-01). Wave-1 packages do NOT edit this file: each fills the stubs in its own partial file.
//
// New state parts (append-only order): ... tunnels, ground, effects, garrison, stats, [extensions].
// Hook call sites placed by M4-01 and the files whose stubs they call:
//   Simulation.Garrison.cs   M4-03  ApplyGarrison (ApplyEnter routing, Simulation.M3.cs), ApplyUnloadCommand (Apply, CommandKind.Unload),
//                                   OnGarrisonBuildingRemoving (OnM3BuildingRemoving, before the building's cells are freed)
//   Missions/GarrisonMission.cs M4-03 GarrisonMission.Handle (MissionKind.Garrisoned, registered in MissionHandlers)
//   Simulation.Stats.cs      M4-06  OnLethalHit (ApplyPendingDamage, health crossing to <= 0), OnStatsBuilt (SpawnProduced*, ApplyPlace),
//                                   OnStatsLost (RunCleanup, before removal), OnStatsHarvested (HarvestMission unload), OnStatsSpent (Spend)
//   Simulation.Ground.cs     M4-05  ApplyWarheadFoam (Detonate, after ApplyWarheadGround)
//   Simulation.Players.cs    M4-04  TierOf; RulesOf becomes per player (signature unchanged)
public sealed partial class Simulation
{
    /// <summary>Neutral-building home owners — the "garrison" part (M4). Occupants themselves live in the "tunnels" part.</summary>
    public GarrisonState Garrison => _garrison;

    /// <summary>Per-player counters — the "stats" part (M4).</summary>
    public StatsState Stats => _stats;

    /// <summary>Counters of one player from the "stats" part (zeros for an unknown slot).</summary>
    public PlayerStats StatsOf(byte player) => _stats.Of(player);

    /// <summary>Number of soldiers garrisoned in <paramref name="building"/> (0 if it is gone). Counts infantry with layer
    /// <see cref="ActorLayer.Garrisoned"/> whose carrier is the building, in slot order.</summary>
    public int OccupantsIn(EntityId building)
    {
        if (!_buildings.Slots.IsAlive(building)) return 0;
        int n = 0;
        for (int i = 1; i < _infantry.Capacity; i++)
            if (_infantry.Slots.IsIndexAlive(i) && _tunnels.InfantryLayer[i] == ActorLayer.Garrisoned && _tunnels.InfantryCarrier[i] == building) n++;
        return n;
    }

    /// <summary>True if the live building's type can hold a garrison (<see cref="Rules.BuildingType.Garrison"/> &gt; 0).</summary>
    internal bool IsGarrisonable(int buildingSlot) => BuildingTypeAt(buildingSlot).Garrison > 0;
}
